'use strict';

const fs = require('fs');
const data = fs.readFileSync(0);
let pos = 0;

function nextInt() {
  while (pos < data.length && data[pos] <= 32) pos++;
  let sign = 1;
  if (data[pos] === 45) {
    sign = -1;
    pos++;
  }
  let value = 0;
  while (pos < data.length && data[pos] > 32) {
    value = value * 10 + data[pos] - 48;
    pos++;
  }
  return value * sign;
}

const L = nextInt();
const C = nextInt();
const matrix = new Int32Array(L * C);

for (let i = 0; i < L * C; i++) {
  matrix[i] = nextInt();
}

const squareCols = C - 1;
const heights = new Int32Array(squareCols);
const stack = new Int32Array(squareCols + 1);
let answer = 0;

for (let i = 0; i < L - 1; i++) {
  const row = i * C;
  for (let j = 0; j < squareCols; j++) {
    const a = matrix[row + j];
    const b = matrix[row + j + 1];
    const c = matrix[row + C + j];
    const d = matrix[row + C + j + 1];

    if (a + d <= b + c) heights[j]++;
    else heights[j] = 0;
  }

  let top = -1;
  for (let j = 0; j <= squareCols; j++) {
    const current = j === squareCols ? 0 : heights[j];

    while (top >= 0 && heights[stack[top]] > current) {
      const height = heights[stack[top--]];
      const left = top < 0 ? 0 : stack[top] + 1;
      const width = j - left;
      const area = (height + 1) * (width + 1);
      if (area > answer) answer = area;
    }

    if (j < squareCols) stack[++top] = j;
  }
}

console.log(answer.toString());
